            lower.append(p)
        for p in reversed(ps):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    hulls = {color: convex_hull(ps) for color, ps in points.items()}

    def edges(poly):
        if len(poly) == 2:
            return [(poly[0], poly[1])]
        if len(poly) > 2:
            return [(poly[i], poly[(i + 1) % len(poly)])
                    for i in range(len(poly))]
        return []

    def draw(color, a, b):
        # Integer Bresenham line, including both endpoints.
        x0, y0 = a[1], a[0]
        x1, y1 = b[1], b[0]
        dx, dy = abs(x1 - x0), abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        while True:
            if 0 <= y0 < h and 0 <= x0 < w and out[y0][x0] == 0:
                out[y0][x0] = color
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy

    def draw_hull(color, poly, dr=0, dc=0):
        for a, b in edges(poly):
            draw(color, (a[0] + dr, a[1] + dc),
                 (b[0] + dr, b[1] + dc))

    # Outline each color's convex hull.
    for color, poly in hulls.items():
